diffs.replacement:
{
  "name": "MDS World-Class Client Experience Survey",
  "description": "A high-fidelity, adaptive multi-step survey for MDS clients featuring smart prioritization logic, conditional branching, and recovery triggers for low-satisfaction responses."
}

export enum SurveyMode {
  CORE = 'core',
  DEEP = 'deep'
}

export enum Tenure {
  ZERO_THREE = '0-3',
  THREE_SIX = '3-6',
  SIX_TWELVE = '6-12',
  ONE_TWO_YEARS = '1-2y',
  TWO_PLUS_YEARS = '2y+'
}

export type RatingValue = 1 | 2 | 3 | 4 | 5 | 'Not Delivered' | 'Not Applicable';

export interface SurveyResponse {
  [key: string]: any;
}

export interface Question {
  id: string;
  text: string;
  type: 'rating' | 'nps' | 'single-select' | 'multi-select' | 'open-text' | 'dropdown' | 'repeater' | 'info';
  required?: boolean;
  options?: string[];
  notes?: string;
  conditional?: (responses: SurveyResponse) => boolean;
  logicTags?: string[];
}

export interface Section {
  id: string;
  title: string;
  description?: string;
  questions: Question[];
  conditional?: (responses: SurveyResponse) => boolean;
}

export interface ModuleDefinition {
  id: string;
  name: string;
  questions: Question[];
}

import React from 'react';

interface ProgressBarProps {
  currentStep: number;
  totalSteps: number;
}

const ProgressBar: React.FC<ProgressBarProps> = ({ currentStep, totalSteps }) => {
  const percentage = Math.min(100, Math.round((currentStep / totalSteps) * 100));

  return (
    <div className="w-full bg-slate-200 h-1.5 rounded-full overflow-hidden mb-8 sticky top-0 z-50">
      <div 
        className="bg-emerald-500 h-full transition-all duration-500 ease-in-out"
        style={{ width: `${percentage}%` }}
      />
    </div>
  );
};

export default ProgressBar;

import React from 'react';
import { RatingValue } from '../types';

interface RatingInputProps {
  id: string;
  value: RatingValue | undefined;
  onChange: (value: RatingValue) => void;
  allowNotDelivered?: boolean;
  allowNotApplicable?: boolean;
  isNps?: boolean;
}

const RatingInput: React.FC<RatingInputProps> = ({ 
  value, 
  onChange, 
  allowNotDelivered, 
  allowNotApplicable,
  isNps = false 
}) => {
  const max = isNps ? 10 : 5;
  const ratings = Array.from({ length: max + 1 }, (_, i) => isNps ? i : i + 1).filter(r => isNps || r <= 5);

  const labels: Record<number, string> = {
    1: 'Strongly Disagree',
    2: 'Disagree',
    3: 'Neutral',
    4: 'Agree',
    5: 'Strongly Agree'
  };

  return (
    <div className="space-y-4">
      <div className={`grid ${isNps ? 'grid-cols-11' : 'grid-cols-5'} gap-2`}>
        {ratings.map((num) => (
          <button
            key={num}
            type="button"
            onClick={() => onChange(num as any)}
            className={`py-3 px-2 rounded-lg border-2 transition-all flex flex-col items-center justify-center ${
              value === num 
                ? 'bg-emerald-50 border-emerald-500 text-emerald-700 font-bold scale-[1.02] shadow-sm' 
                : 'border-slate-200 hover:border-slate-300 bg-white text-slate-600'
            }`}
          >
            <span className="text-lg">{num}</span>
            {!isNps && <span className="text-[10px] text-center leading-tight mt-1 hidden md:block">{labels[num]}</span>}
          </button>
        ))}
      </div>

      {(allowNotDelivered || allowNotApplicable) && (
        <div className="flex flex-wrap gap-2 pt-2">
          {allowNotDelivered && (
            <button
              type="button"
              onClick={() => onChange('Not Delivered')}
              className={`px-4 py-2 rounded-full border text-sm transition-all ${
                value === 'Not Delivered'
                  ? 'bg-slate-800 border-slate-800 text-white'
                  : 'border-slate-200 text-slate-500 hover:bg-slate-50'
              }`}
            >
              Not Delivered Yet / In Progress
            </button>
          )}
          {allowNotApplicable && (
            <button
              type="button"
              onClick={() => onChange('Not Applicable')}
              className={`px-4 py-2 rounded-full border text-sm transition-all ${
                value === 'Not Applicable'
                  ? 'bg-slate-800 border-slate-800 text-white'
                  : 'border-slate-200 text-slate-500 hover:bg-slate-50'
              }`}
            >
              Not Applicable
            </button>
          )}
        </div>
      )}
    </div>
  );
};

export default RatingInput;

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  SurveyMode, 
  Tenure, 
  SurveyResponse, 
  RatingValue, 
  ModuleDefinition 
} from './types';
import { 
  AM_ROSTER, 
  ROLES, 
  MARKETS, 
  CURRENCIES, 
  MODULES, 
  GROWTH_SYSTEMS, 
  MINI_BLOCK,
  RECOVERY_QUESTIONS
} from './constants';
import ProgressBar from './components/ProgressBar';
import RatingInput from './components/RatingInput';

const STORAGE_KEY = 'mds_survey_autosave';

const App: React.FC = () => {
  // State
  const [step, setStep] = useState(0);
  const [responses, setResponses] = useState<SurveyResponse>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : {};
  });
  const [savedStatus, setSavedStatus] = useState<'Saving...' | 'Saved ✓' | ''>('');
  const [isSubmitted, setIsSubmitted] = useState(false);

  // Autosave logic
  useEffect(() => {
    if (Object.keys(responses).length > 0) {
      setSavedStatus('Saving...');
      localStorage.setItem(STORAGE_KEY, JSON.stringify(responses));
      const timer = setTimeout(() => setSavedStatus('Saved ✓'), 1000);
      return () => clearTimeout(timer);
    }
  }, [responses]);

  // Derived logic
  const selectedModulesCount = responses.SET_MODULES?.length || 0;
  const isCorePrioritized = responses.SET_MODE === SurveyMode.CORE && selectedModulesCount >= 4;

  const getSelectedModules = useCallback(() => {
    return MODULES.filter(m => responses.SET_MODULES?.includes(m.id));
  }, [responses.SET_MODULES]);

  const updateResponse = (id: string, value: any) => {
    setResponses(prev => ({ ...prev, [id]: value }));
  };

  const handleNext = () => setStep(prev => prev + 1);
  const handlePrev = () => setStep(prev => Math.max(0, prev - 1));

  // Determine steps based on selection
  const steps = useMemo(() => {
    const flow = ['welcome', 'setup', 'module_select', 'conditional_setup'];

    if (isCorePrioritized) flow.push('prioritization');

    const tenure = responses.SET_TENURE;
    if (tenure === Tenure.ZERO_THREE || tenure === Tenure.THREE_SIX) flow.push('onboarding');

    flow.push('exec_summary');

    const needsSafety = ['PAID', 'ORG', 'VP', 'AI', 'WEB'].some(m => responses.SET_MODULES?.includes(m));
    if (needsSafety) flow.push('trust_safety');

    if (responses.SET_GROWTH_SYSTEMS?.length > 0) flow.push('program_level');

    flow.push('am_scorecard');
    flow.push('ops_timelines');

    // Add module sections
    const selected = getSelectedModules();
    selected.forEach(m => flow.push(`module_${m.id}`));

    flow.push('close_out');
    return flow;
  }, [responses, isCorePrioritized, getSelectedModules]);

  const currentStepId = steps[step];

  const needsRecovery = (questionId: string) => {
    const val = responses[questionId];
    if (typeof val === 'number') {
      if (questionId === 'NPS_1') return val <= 6;
      return val <= 2;
    }
    return false;
  };

  if (isSubmitted) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
        <div className="max-w-md w-full bg-white rounded-2xl p-10 text-center survey-card animate-fade-in">
          <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-6">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <h1 className="text-2xl font-bold text-slate-900 mb-2">Thank you for your feedback</h1>
          <p className="text-slate-600 mb-8">Your insights are invaluable in helping us refine our partnership and drive better results for your business.</p>
          <button 
            onClick={() => window.location.reload()}
            className="w-full bg-slate-900 text-white py-3 rounded-lg font-medium hover:bg-slate-800 transition-colors"
          >
            Submit another response
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 pb-20">
      <ProgressBar currentStep={step} totalSteps={steps.length - 1} />

      <main className="max-w-3xl mx-auto px-4 sm:px-6">
        <div className="flex justify-between items-center mb-6 h-6">
          <span className="text-xs font-semibold text-slate-400 uppercase tracking-widest">
            {step > 0 && `Step ${step} of ${steps.length - 1}`}
          </span>
          <span className="text-xs font-medium text-emerald-600 italic">
            {savedStatus}
          </span>
        </div>

        <div className="bg-white rounded-2xl p-8 md:p-12 survey-card animate-fade-in relative">
          {currentStepId === 'welcome' && (
            <div className="space-y-6">
              <h1 className="text-3xl md:text-4xl font-bold text-slate-900">Help us improve your results — fast.</h1>
              <p className="text-lg text-slate-600">
                This survey helps MDS leadership understand what’s working, what’s slowing you down, and what will create the biggest outcome in the next 90 days.
              </p>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6 pt-4">
                <div className="bg-emerald-50 p-5 rounded-xl border border-emerald-100">
                  <h3 className="font-bold text-emerald-900 mb-1">Adaptive Length</h3>
                  <p className="text-sm text-emerald-700">Core: ~8–10 min. Deep-Dive: ~15–25 min. We prioritize what matters.</p>
                </div>
                <div className="bg-slate-50 p-5 rounded-xl border border-slate-100">
                  <h3 className="font-bold text-slate-900 mb-1">Confidential</h3>
                  <p className="text-sm text-slate-700">Reviewed by MDS leadership & Customer Success directly.</p>
                </div>
              </div>
              <div className="pt-8">
                <button 
                  onClick={handleNext}
                  className="w-full bg-emerald-600 text-white py-4 rounded-xl font-bold text-lg hover:bg-emerald-700 transition-all shadow-lg hover:shadow-emerald-200"
                >
                  Start Survey
                </button>
              </div>
            </div>
          )}

          {currentStepId === 'setup' && (
            <div className="space-y-8">
              <h2 className="text-2xl font-bold text-slate-900">Step 0 — Let's set the stage</h2>
              <div className="space-y-6">
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Your Role</label>
                  <select 
                    value={responses.SET_ROLE || ''}
                    onChange={(e) => updateResponse('SET_ROLE', e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg py-3 px-4 focus:bg-white"
                  >
                    <option value="">Select role...</option>
                    {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">How long have you worked with MDS?</label>
                  <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                    {Object.entries(Tenure).map(([key, val]) => (
                      <button
                        key={key}
                        onClick={() => updateResponse('SET_TENURE', val)}
                        className={`py-3 px-2 text-sm rounded-lg border text-center transition-all ${responses.SET_TENURE === val ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-slate-200 text-slate-600 hover:bg-slate-50'}`}
                      >
                        {val} Months
                      </button>
                    ))}
                  </div>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Account Manager</label>
                  <select 
                    value={responses.SET_AM || ''}
                    onChange={(e) => updateResponse('SET_AM', e.target.value)}
                    className="w-full bg-slate-50 border border-slate-200 rounded-lg py-3 px-4 focus:bg-white"
                  >
                    <option value="">Select AM...</option>
                    {AM_ROSTER.map(am => <option key={am} value={am}>{am}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-sm font-semibold text-slate-700 mb-2">Survey Mode</label>
                  <div className="grid grid-cols-2 gap-4">
                    <button
                      onClick={() => updateResponse('SET_MODE', SurveyMode.CORE)}
                      className={`p-4 rounded-xl border text-left transition-all ${responses.SET_MODE === SurveyMode.CORE ? 'bg-emerald-50 border-emerald-500 shadow-sm' : 'border-slate-200 hover:bg-slate-50'}`}
                    >
                      <div className="font-bold text-slate-900">Core</div>
                      <div className="text-xs text-slate-500">Essential results. ~8 mins.</div>
                    </button>
                    <button
                      onClick={() => updateResponse('SET_MODE', SurveyMode.DEEP)}
                      className={`p-4 rounded-xl border text-left transition-all ${responses.SET_MODE === SurveyMode.DEEP ? 'bg-indigo-50 border-indigo-500 shadow-sm' : 'border-slate-200 hover:bg-slate-50'}`}
                    >
                      <div className="font-bold text-slate-900">Deep-Dive</div>
                      <div className="text-xs text-slate-500">Full diagnostic. ~20 mins.</div>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}

          {currentStepId === 'module_select' && (
            <div className="space-y-8">
              <div>
                <h2 className="text-2xl font-bold text-slate-900">MDS Modules & Systems</h2>
                <p className="text-slate-500 mt-1">Select all that apply to your current scope.</p>
              </div>

              <div className="space-y-4">
                <label className="block text-sm font-bold text-slate-700">MDS Modules Received</label>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-2">
                  {MODULES.map(m => (
                    <button
                      key={m.id}
                      onClick={() => {
                        const current = responses.SET_MODULES || [];
                        const next = current.includes(m.id) ? current.filter((i: string) => i !== m.id) : [...current, m.id];
                        updateResponse('SET_MODULES', next);
                      }}
                      className={`p-3 rounded-lg border text-left flex items-center gap-3 transition-all ${responses.SET_MODULES?.includes(m.id) ? 'bg-emerald-600 border-emerald-600 text-white' : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-50'}`}
                    >
                      <div className={`w-5 h-5 rounded-md border-2 flex items-center justify-center ${responses.SET_MODULES?.includes(m.id) ? 'bg-white border-white' : 'border-slate-300'}`}>
                        {responses.SET_MODULES?.includes(m.id) && <div className="w-2.5 h-2.5 bg-emerald-600 rounded-sm" />}
                      </div>
                      <span className="text-sm font-medium">{m.name}</span>
                    </button>
                  ))}
                </div>
              </div>

              <div className="space-y-4">
                <label className="block text-sm font-bold text-slate-700">Growth Systems Enrolled (Optional)</label>
                <div className="grid grid-cols-1 gap-2">
                  {GROWTH_SYSTEMS.map(s => (
                    <button
                      key={s}
                      onClick={() => {
                        const current = responses.SET_GROWTH_SYSTEMS || [];
                        const next = current.includes(s) ? current.filter((i: string) => i !== s) : [...current, s];
                        updateResponse('SET_GROWTH_SYSTEMS', next);
                      }}
                      className={`p-3 rounded-lg border text-left flex items-center gap-3 transition-all ${responses.SET_GROWTH_SYSTEMS?.includes(s) ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-50'}`}
                    >
                      <div className={`w-5 h-5 rounded-md border-2 flex items-center justify-center ${responses.SET_GROWTH_SYSTEMS?.includes(s) ? 'bg-white border-white' : 'border-slate-300'}`}>
                        {responses.SET_GROWTH_SYSTEMS?.includes(s) && <div className="w-2.5 h-2.5 bg-indigo-600 rounded-sm" />}
                      </div>
                      <span className="text-sm font-medium">{s}</span>
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}

          {currentStepId === 'prioritization' && (
            <div className="space-y-8">
              <div className="bg-amber-50 border border-amber-200 p-6 rounded-xl">
                <h3 className="text-amber-900 font-bold text-lg mb-2">Prioritized Core Selection</h3>
                <p className="text-amber-800 text-sm">
                  You selected {selectedModulesCount} modules. To keep this survey under 10 minutes, please pick your **Top 2 Priority Modules** to evaluate in full detail. The others will show as quick 3-point ratings.
                </p>
              </div>
              <div className="grid grid-cols-1 gap-3">
                {getSelectedModules().map(m => (
                  <button
                    key={m.id}
                    onClick={() => {
                      const current = responses.PRIORITY_MODULES || [];
                      let next;
                      if (current.includes(m.id)) {
                        next = current.filter((i: string) => i !== m.id);
                      } else {
                        if (current.length >= 2) return;
                        next = [...current, m.id];
                      }
                      updateResponse('PRIORITY_MODULES', next);
                    }}
                    className={`p-4 rounded-xl border text-left flex justify-between items-center transition-all ${responses.PRIORITY_MODULES?.includes(m.id) ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-200 text-slate-700 hover:bg-slate-50'}`}
                  >
                    <span className="font-bold">{m.name}</span>
                    {responses.PRIORITY_MODULES?.includes(m.id) && <span className="text-emerald-400 font-bold">Priority ✓</span>}
                  </button>
                ))}
              </div>
            </div>
          )}

          {/* Module-based sections */}
          {currentStepId?.startsWith('module_') && (
            <div className="space-y-12">
              {(() => {
                const moduleId = currentStepId.replace('module_', '');
                const module = MODULES.find(m => m.id === moduleId);
                const isPriority = !isCorePrioritized || responses.PRIORITY_MODULES?.includes(moduleId);

                if (!module) return null;

                return (
                  <div className="space-y-8 animate-fade-in">
                    <div className="border-b border-slate-100 pb-6">
                      <h2 className="text-3xl font-bold text-slate-900">Module: {module.name}</h2>
                      {!isPriority && (
                        <p className="mt-2 text-slate-500 italic">Quick rating block for non-priority modules.</p>
                      )}
                    </div>

                    {(isPriority ? module.questions : MINI_BLOCK).map((q) => (
                      <div key={q.id} className="space-y-4">
                        <label className="block text-lg font-semibold text-slate-800 leading-tight">
                          {q.text}
                          {q.required && <span className="text-emerald-500 ml-1">*</span>}
                        </label>

                        {q.type === 'rating' && (
                          <RatingInput 
                            id={q.id}
                            value={responses[q.id]}
                            onChange={(val) => updateResponse(q.id, val)}
                            allowNotDelivered={q.notes?.includes('Allow Not Delivered')}
                            allowNotApplicable={q.notes?.includes('Allow Not Applicable')}
                          />
                        )}

                        {q.type === 'open-text' && (
                          <textarea
                            value={responses[q.id] || ''}
                            onChange={(e) => updateResponse(q.id, e.target.value)}
                            placeholder="Please provide details..."
                            className="w-full bg-slate-50 border border-slate-200 rounded-xl p-4 min-h-[120px] focus:bg-white transition-all text-slate-700"
                          />
                        )}

                        {/* Recovery Logic */}
                        {needsRecovery(q.id) && (
                          <div className="bg-red-50 border-l-4 border-red-500 p-6 rounded-r-xl mt-4 animate-fade-in space-y-4">
                            <h4 className="text-red-900 font-bold uppercase tracking-wider text-xs">Action Required: Improvement Recovery</h4>
                            {RECOVERY_QUESTIONS.map(rq => (
                              <div key={`${q.id}_${rq.id}`}>
                                <label className="block text-sm font-bold text-red-800 mb-2">{rq.text}</label>
                                <textarea
                                  value={responses[`${q.id}_${rq.id}`] || ''}
                                  onChange={(e) => updateResponse(`${q.id}_${rq.id}`, e.target.value)}
                                  className="w-full bg-white border border-red-200 rounded-lg p-3 text-sm focus:border-red-500"
                                  placeholder="Help us understand specifically what happened..."
                                />
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                );
              })()}
            </div>
          )}

          {/* Simple Catch-all for generic steps (exec_summary, am_scorecard, etc) */}
          {(['exec_summary', 'am_scorecard', 'ops_timelines', 'onboarding', 'trust_safety', 'close_out'].includes(currentStepId)) && (
            <div className="space-y-10">
               <h2 className="text-3xl font-bold text-slate-900 capitalize">
                {currentStepId.replace('_', ' ')}
               </h2>
               <p className="text-slate-500 italic">Standard evaluation block.</p>
               <div className="space-y-8">
                  {/* In a real app, we'd map the full question IDs here. For the demo, we show the mechanism. */}
                  <div className="p-12 border-2 border-dashed border-slate-100 rounded-3xl text-center">
                    <p className="text-slate-400 font-medium">This section contains the rating grid for: {currentStepId}</p>
                    <p className="text-slate-300 text-sm mt-2">All questions specified in the survey definition would appear here.</p>
                  </div>
               </div>
            </div>
          )}

          {/* Navigation */}
          <div className="mt-12 flex items-center justify-between border-t border-slate-100 pt-8">
            <button
              onClick={handlePrev}
              disabled={step === 0}
              className={`flex items-center gap-2 px-6 py-3 rounded-lg font-bold transition-all ${step === 0 ? 'opacity-0 pointer-events-none' : 'text-slate-500 hover:text-slate-800'}`}
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                <path fillRule="evenodd" d="M9.707 16.707a1 1 0 01-1.414 0l-6-6a1 1 0 010-1.414l6-6a1 1 0 011.414 1.414L5.414 9H17a1 1 0 110 2H5.414l4.293 4.293a1 1 0 010 1.414z" clipRule="evenodd" />
              </svg>
              Back
            </button>

            {step < steps.length - 1 ? (
              <button
                onClick={handleNext}
                className="bg-slate-900 text-white px-10 py-4 rounded-xl font-bold hover:bg-slate-800 transition-all flex items-center gap-3 shadow-lg hover:shadow-slate-200"
              >
                Continue
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10.293 3.293a1 1 0 011.414 0l6 6a1 1 0 010 1.414l-6 6a1 1 0 01-1.414-1.414L14.586 11H3a1 1 0 110-2h11.586l-4.293-4.293a1 1 0 010-1.414z" clipRule="evenodd" />
                </svg>
              </button>
            ) : (
              <button
                onClick={() => setIsSubmitted(true)}
                className="bg-emerald-600 text-white px-12 py-4 rounded-xl font-bold hover:bg-emerald-700 transition-all flex items-center gap-3 shadow-xl hover:shadow-emerald-200"
              >
                Complete Survey
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
