import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { 
  SurveyMode, 
  Tenure, 
  SurveyResponse, 
  RatingValue, 
  ModuleDefinition,
  Question
} from './types';
import { 
  AM_ROSTER, 
  ROLES, 
  MARKETS, 
  CURRENCIES, 
  MODULES, 
  GROWTH_SYSTEMS, 
  MINI_BLOCK_QUESTIONS,
  RECOVERY_QUESTIONS,
  SPEND_BANDS
} from './constants';
import ProgressBar from './components/ProgressBar';
import RatingInput from './components/RatingInput';

const STORAGE_KEY = 'mds_survey_autosave_v2';

const App: React.FC = () => {
  const [step, setStep] = useState(0);
  const [responses, setResponses] = useState<SurveyResponse>(() => {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : {};
  });
  const [savedStatus, setSavedStatus] = useState<'Saving...' | 'Saved ✓' | ''>('');
  const [isSubmitted, setIsSubmitted] = useState(false);
  const [showSaveModal, setShowSaveModal] = useState(false);

  useEffect(() => {
    if (Object.keys(responses).length > 0) {
      setSavedStatus('Saving...');
      localStorage.setItem(STORAGE_KEY, JSON.stringify(responses));
      const timer = setTimeout(() => setSavedStatus('Saved ✓'), 1000);
      return () => clearTimeout(timer);
    }
  }, [responses]);

  const updateResponse = (id: string, value: any) => {
    setResponses(prev => ({ ...prev, [id]: value }));
  };

  const handleNext = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setStep(prev => prev + 1);
  };
  const handlePrev = () => {
    window.scrollTo({ top: 0, behavior: 'smooth' });
    setStep(prev => Math.max(0, prev - 1));
  };

  const selectedModulesCount = (responses.SET_MODULES || []).length;
  const isCorePrioritized = responses.SET_MODE === SurveyMode.CORE && selectedModulesCount >= 4;

  const steps = useMemo(() => {
    const flow = ['welcome', 'setup', 'module_select'];

    // Conditional Setup
    if (responses.SET_MODULES?.includes('ORG') || responses.SET_MODULES?.includes('PAID') || responses.SET_MODULES?.includes('AI')) {
      flow.push('conditional_setup');
    }

    if (isCorePrioritized) flow.push('prioritization');

    const tenure = responses.SET_TENURE;
    if (tenure === Tenure.ZERO_THREE || tenure === Tenure.THREE_SIX) flow.push('onboarding');

    flow.push('exec_summary');

    const needsSafety = ['PAID', 'ORG', 'VP', 'AI', 'WEB'].some(m => responses.SET_MODULES?.includes(m));
    if (needsSafety) flow.push('trust_safety');

    if (responses.SET_GROWTH_SYSTEMS?.length > 0) {
      responses.SET_GROWTH_SYSTEMS.forEach((_: any, i: number) => flow.push(`growth_system_${i}`));
    }

    flow.push('am_scorecard');
    flow.push('ops_timelines');

    const selected = MODULES.filter(m => responses.SET_MODULES?.includes(m.id));
    selected.forEach(m => flow.push(`module_${m.id}`));

    flow.push('close_out');
    return flow;
  }, [responses, isCorePrioritized]);

  const currentStepId = steps[step];

  const needsRecovery = (questionId: string) => {
    const val = responses[questionId];
    if (typeof val === 'number') {
      if (questionId === 'NPS_1') return val <= 6;
      return val <= 2;
    }
    return false;
  };

  const renderRatingQuestion = (q: Question, prefix = '') => {
    const fullId = prefix ? `${prefix}_${q.id}` : q.id;
    return (
      <div key={fullId} className="space-y-4 animate-fade-in border-b border-slate-50 pb-8 last:border-0">
        <label className="block text-lg font-semibold text-slate-800 leading-tight">
          {q.text}
          {q.required && <span className="text-emerald-500 ml-1">*</span>}
        </label>

        {q.type === 'rating' || q.type === 'nps' ? (
          <RatingInput 
            id={fullId}
            value={responses[fullId]}
            onChange={(val) => updateResponse(fullId, val)}
            allowNotDelivered={q.allowNotDelivered}
            allowNotApplicable={q.allowNotApplicable}
            isNps={q.type === 'nps'}
          />
        ) : q.type === 'open-text' ? (
          <textarea
            value={responses[fullId] || ''}
            onChange={(e) => updateResponse(fullId, e.target.value)}
            placeholder="Please provide details..."
            className="w-full bg-slate-50 border border-slate-200 rounded-xl p-4 min-h-[100px] focus:bg-white transition-all text-slate-700"
          />
        ) : q.type === 'single-select' && q.options ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
            {q.options.map((opt: any) => (
              <button
                key={typeof opt === 'string' ? opt : opt.value}
                onClick={() => updateResponse(fullId, typeof opt === 'string' ? opt : opt.value)}
                className={`p-3 rounded-lg border text-left transition-all ${responses[fullId] === (typeof opt === 'string' ? opt : opt.value) ? 'bg-slate-900 border-slate-900 text-white' : 'bg-white border-slate-200 hover:bg-slate-50'}`}
              >
                {typeof opt === 'string' ? opt : opt.label}
              </button>
            ))}
          </div>
        ) : null}

        {needsRecovery(fullId) && (
          <div className="bg-red-50 border-l-4 border-red-500 p-6 rounded-r-xl mt-4 space-y-4">
            <h4 className="text-red-900 font-bold uppercase tracking-wider text-[10px]">Quick follow-up so we can fix this</h4>
            {RECOVERY_QUESTIONS.map(rq => (
              <div key={`${fullId}_${rq.id}`}>
                <label className="block text-xs font-bold text-red-800 mb-1">{rq.text}</label>
                <textarea
                  value={responses[`${fullId}_${rq.id}`] || ''}
                  onChange={(e) => updateResponse(`${fullId}_${rq.id}`, e.target.value)}
                  className="w-full bg-white border border-red-200 rounded-lg p-3 text-sm focus:border-red-500"
                  placeholder="Example: Communication was slow last week..."
                />
              </div>
            ))}
          </div>
        )}
      </div>
    );
  };

  if (isSubmitted) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-slate-50 p-6">
        <div className="max-w-xl w-full bg-white rounded-3xl p-12 text-center survey-card animate-fade-in">
          <div className="w-20 h-20 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-8 shadow-inner">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-10 w-10" fill="none" viewBox="0 0 24 24" stroke="currentColor">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M5 13l4 4L19 7" />
            </svg>
          </div>
          <h1 className="text-3xl font-bold text-slate-900 mb-4">Submission Received</h1>
          <p className="text-slate-600 mb-10 text-lg leading-relaxed">
            Thank you. Your feedback will be reviewed by MDS leadership. If you requested follow-up, your Account Manager will reach out via your preferred channel.
          </p>
          <div className="bg-slate-50 rounded-2xl p-6 text-left mb-10 border border-slate-100">
            <h3 className="font-bold text-slate-800 mb-2">What happens next?</h3>
            <ul className="text-sm text-slate-600 space-y-2 list-disc list-inside">
              <li>MDS leadership reviews all high-risk items within 48 hours.</li>
              <li>Operational adjustments are planned for the next 90-day cycle.</li>
              <li>Summary report shared with your Account Manager.</li>
            </ul>
          </div>
          <button onClick={() => window.location.reload()} className="text-emerald-600 font-bold hover:underline">Start a new survey</button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50 flex flex-col">
      <ProgressBar currentStep={step} totalSteps={steps.length - 1} />

      <main className="flex-1 max-w-3xl mx-auto px-4 sm:px-6 w-full pb-32">
        <div className="flex justify-between items-center mb-6 pt-6">
          <div className="flex items-center gap-3">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Step {step} of {steps.length - 1}</span>
            <div className="h-1 w-1 rounded-full bg-slate-300" />
            <span className="text-[10px] font-bold text-emerald-600 uppercase tracking-[0.1em]">{savedStatus}</span>
          </div>
          {step > 0 && (
            <button 
              onClick={() => setShowSaveModal(true)}
              className="text-[10px] font-bold text-slate-500 hover:text-slate-900 uppercase tracking-widest transition-colors"
            >
              Save & Exit
            </button>
          )}
        </div>

        <div className="bg-white rounded-3xl p-8 md:p-14 survey-card animate-fade-in">
          {currentStepId === 'welcome' && (
            <div className="space-y-10">
              <div className="space-y-4">
                <h1 className="text-4xl md:text-5xl font-black text-slate-900 tracking-tight leading-none">Help us improve your results — fast.</h1>
                <p className="text-xl text-slate-500 leading-relaxed font-medium">
                  A short, confidential survey reviewed by MDS leadership to strengthen delivery and outcomes in the next 90 days.
                </p>
              </div>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-4 py-4">
                {[
                  { title: 'Confidential', desc: 'Reviewed by MDS leadership directly.', icon: '🔒' },
                  { title: 'Smart Flow', desc: 'Questions tailored to your scope.', icon: '⚡' },
                  { title: 'Autosaved', desc: 'Resume exactly where you left off.', icon: '💾' }
                ].map((item, i) => (
                  <div key={i} className="p-5 rounded-2xl bg-slate-50 border border-slate-100 hover:border-emerald-200 transition-colors group">
                    <div className="text-2xl mb-3">{item.icon}</div>
                    <h3 className="font-bold text-slate-900 mb-1 group-hover:text-emerald-600">{item.title}</h3>
                    <p className="text-xs text-slate-500 leading-normal">{item.desc}</p>
                  </div>
                ))}
              </div>

              <div className="pt-6 space-y-4">
                <button 
                  onClick={handleNext}
                  className="w-full bg-emerald-600 text-white py-5 rounded-2xl font-black text-xl hover:bg-emerald-700 transition-all shadow-xl shadow-emerald-200 active:scale-[0.98]"
                >
                  Start Survey
                </button>
                <p className="text-center text-xs text-slate-400 font-medium tracking-tight">
                  Takes ~8–10 minutes for Core mode.
                </p>
              </div>
            </div>
          )}

          {currentStepId === 'setup' && (
            <div className="space-y-10">
              <div className="space-y-2">
                <h2 className="text-3xl font-black text-slate-900 tracking-tight">Step 0 — Setup</h2>
                <p className="text-slate-500 font-medium">Basic info to route your feedback correctly.</p>
              </div>
              <div className="space-y-8">
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Your Role</label>
                  <select 
                    value={responses.SET_ROLE || ''}
                    onChange={(e) => updateResponse('SET_ROLE', e.target.value)}
                    className="w-full bg-slate-50 border-2 border-slate-100 rounded-xl py-4 px-6 focus:border-emerald-500 focus:bg-white transition-all text-slate-900 font-semibold text-lg"
                  >
                    <option value="">Select role...</option>
                    {ROLES.map(r => <option key={r} value={r}>{r}</option>)}
                  </select>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Partnership Tenure</label>
                  <div className="grid grid-cols-2 sm:grid-cols-3 gap-2">
                    {Object.entries(Tenure).map(([key, val]) => (
                      <button
                        key={key}
                        onClick={() => updateResponse('SET_TENURE', val)}
                        className={`py-4 rounded-xl border-2 font-bold transition-all ${responses.SET_TENURE === val ? 'bg-emerald-600 border-emerald-600 text-white shadow-lg' : 'bg-white border-slate-100 text-slate-500 hover:border-slate-200'}`}
                      >
                        {val} Months
                      </button>
                    ))}
                  </div>
                </div>
                <div>
                  <label className="block text-xs font-bold text-slate-400 uppercase tracking-widest mb-3">Survey Mode</label>
                  <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                    <button
                      onClick={() => updateResponse('SET_MODE', SurveyMode.CORE)}
                      className={`p-6 rounded-2xl border-2 text-left transition-all relative overflow-hidden group ${responses.SET_MODE === SurveyMode.CORE ? 'border-emerald-500 bg-emerald-50 shadow-inner' : 'border-slate-100 hover:border-slate-200'}`}
                    >
                      <div className={`text-lg font-black mb-1 ${responses.SET_MODE === SurveyMode.CORE ? 'text-emerald-900' : 'text-slate-900'}`}>Core</div>
                      <div className={`text-xs font-medium ${responses.SET_MODE === SurveyMode.CORE ? 'text-emerald-700' : 'text-slate-500'}`}>Essential results. ~8 mins.</div>
                      {responses.SET_MODE === SurveyMode.CORE && <div className="absolute top-2 right-2 text-emerald-500">✓</div>}
                    </button>
                    <button
                      onClick={() => updateResponse('SET_MODE', SurveyMode.DEEP)}
                      className={`p-6 rounded-2xl border-2 text-left transition-all relative overflow-hidden group ${responses.SET_MODE === SurveyMode.DEEP ? 'border-indigo-500 bg-indigo-50 shadow-inner' : 'border-slate-100 hover:border-slate-200'}`}
                    >
                      <div className={`text-lg font-black mb-1 ${responses.SET_MODE === SurveyMode.DEEP ? 'text-indigo-900' : 'text-slate-900'}`}>Deep-Dive</div>
                      <div className={`text-xs font-medium ${responses.SET_MODE === SurveyMode.DEEP ? 'text-indigo-700' : 'text-slate-500'}`}>Full diagnostic. ~25 mins.</div>
                      {responses.SET_MODE === SurveyMode.DEEP && <div className="absolute top-2 right-2 text-indigo-500">✓</div>}
                    </button>
                  </div>
                </div>
              </div>
            </div>
          )}

          {currentStepId === 'module_select' && (
            <div className="space-y-10">
              <div className="space-y-2">
                <h2 className="text-3xl font-black text-slate-900 tracking-tight">Scope Selection</h2>
                <p className="text-slate-500 font-medium">Select the modules you received from MDS.</p>
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                {MODULES.map(m => (
                  <button
                    key={m.id}
                    onClick={() => {
